// MASLD-Bench site — shared nav + eligible leaderboard renderer.
// Data: assets/leaderboard.json (generated by site/export_site_json.py
// from results/eligible/*.tsv). Aggregate metrics only.
(function () {
  var page = document.body.dataset.page || "";
  document.querySelectorAll("nav.site a").forEach(function (a) {
    if (a.dataset.page === page) a.classList.add("on");
  });
})();

function fmt(v, d) {
  if (v === null || v === undefined) return "—";
  if (Math.abs(v) >= 10000) return v.toExponential(2);
  return Number(v).toFixed(d === undefined ? 3 : d);
}
function pct(v) { if (v === null || v === undefined) return "—"; return (v * 100).toFixed(1) + "%"; }

var state = { task: "MB-2001", manifest: "all", sortKey: null, sortDesc: true, query: "" };

var TASK_KIND = { "MB-2001":"regression-free", "MB-2002":"regression-free", "MB-2003":"regression-free",
                  "MB-2005":"regression", "MB-2006":"regression" };
function isRegression(task) { return TASK_KIND[task] === "regression"; }
function primary(r) { return isRegression(state.task) ? r.mae_failure_aware : r.accuracy; }
function betterHigh() { return !isRegression(state.task); }
function taskDef(data) { return (data.meta.task_defs || {})[state.task] || {}; }
function manifestRows(data) {
  var g = data.pairwise_by_manifest || {};
  var out = [];
  Object.keys(g).sort().forEach(function (m) {
    g[m].forEach(function (r) { var c = Object.assign({}, r); c._manifest = m; out.push(c); });
  });
  return out;
}

function rowsForCurrent(data) {
  if (state.task === "MB-2003") {
    var rows = manifestRows(data);
    if (state.manifest !== "all") rows = rows.filter(function (r) { return r._manifest.indexOf(state.manifest) === 0; });
    return rows;
  }
  return (data.eligible || []).filter(function (r) { return r.task === state.task; });
}

function render() {
  var data = window.MASLD_DATA, tbody = document.getElementById("lb-body");
  if (!tbody || !data) return;
  var rows = rowsForCurrent(data).slice();
  var q = state.query.trim().toLowerCase();
  if (q) rows = rows.filter(function (r) {
    return (r.label || r.model).toLowerCase().indexOf(q) >= 0 || r.model.toLowerCase().indexOf(q) >= 0;
  });
  var key = state.sortKey, desc = state.sortDesc;
  rows.sort(function (a, b) {
    var x, y;
    if (key === "model") { x = (a.label || a.model); y = (b.label || b.model); return desc ? x.localeCompare(y) : y.localeCompare(x); }
    if (key === "primary") { x = primary(a); y = primary(b); }
    else { x = a[key]; y = b[key]; }
    if (x === null || x === undefined) return 1;
    if (y === null || y === undefined) return -1;
    return desc ? (y - x) : (x - y);
  });
  var reg = isRegression(state.task);
  var bestVal = null;
  rows.forEach(function (r) {
    var v = primary(r);
    if (v === null || v === undefined || !(r.valid > 0)) return;
    if (bestVal === null) { bestVal = v; return; }
    bestVal = betterHigh() ? Math.max(bestVal, v) : Math.min(bestVal, v);
  });
  var atBest = rows.filter(function (r) {
    var v = primary(r);
    return v !== null && v !== undefined && r.valid > 0 && v === bestVal;
  }).length;
  document.getElementById("lb-count").textContent = rows.length + " row(s)";
  var head = document.getElementById("lb-head");
  if (reg) {
    head.innerHTML = "<th data-k='model'>Model</th>" +
      "<th class='num' data-k='n'>n</th><th class='num' data-k='valid'>valid</th>" +
      "<th class='num' data-k='mae'>MAE (all, raw) ↓</th>" +
      "<th class='num' data-k='mae_in_domain'>MAE in-domain ↓</th>" +
      "<th class='num' data-k='mae_failure_aware'>MAE failure-aware ↓</th>" +
      "<th class='num' data-k='spearman'>Spearman ρ</th>";
  } else if (state.task === "MB-2003") {
    head.innerHTML = "<th data-k='model'>Model</th><th>Manifest</th>" +
      "<th class='num' data-k='n'>n</th><th class='num' data-k='valid'>valid</th>" +
      "<th class='num' data-k='accuracy'>Accuracy</th><th class='num'>95% CI</th>";
  } else {
    head.innerHTML = "<th data-k='model'>Model</th>" +
      "<th class='num' data-k='n'>n</th><th class='num' data-k='valid'>valid</th>" +
      "<th class='num' data-k='accuracy'>Accuracy</th><th class='num'>95% CI</th>";
  }
  head.querySelectorAll("th[data-k]").forEach(function (th) {
    th.onclick = function () {
      var k = th.dataset.k;
      if (state.sortKey === k) state.sortDesc = !state.sortDesc;
      else { state.sortKey = k; state.sortDesc = k !== "model"; }
      render();
    };
    if (state.sortKey === th.dataset.k) th.classList.add("sorted");
  });
  tbody.innerHTML = rows.map(function (r) {
    var v = primary(r);
    var best = atBest === 1 && bestVal !== null && v !== null && v !== undefined && v === bestVal;
    var manifestCell = (state.task === "MB-2003") ? "<td class='mono small'>" + r._manifest.replace("pairwise_manifest_", "M") + "</td>" : "";
    if (reg) {
      return "<tr" + (best ? " class='best'" : "") + ">" +
        "<td class='mono'>" + (r.label || r.model) + "</td>" +
        "<td class='num'>" + r.n + "</td>" +
        "<td class='num'>" + r.valid + "</td>" +
        "<td class='num'>" + fmt(r.mae, 3) + "</td>" +
        "<td class='num'>" + fmt(r.mae_in_domain, 3) + "</td>" +
        "<td class='num'><b>" + fmt(r.mae_failure_aware, 3) + "</b></td>" +
        "<td class='num'>" + (r.spearman === null ? "—" : fmt(r.spearman, 3)) + "</td></tr>";
    }
    return "<tr" + (best ? " class='best'" : "") + ">" +
      "<td class='mono'>" + (r.label || r.model) + "</td>" + manifestCell +
      "<td class='num'>" + r.n + "</td>" +
      "<td class='num'>" + r.valid + "</td>" +
      "<td class='num'><b>" + pct(r.accuracy) + "</b></td>" +
      "<td class='num'>" + fmt(r.ci_lo, 3) + "–" + fmt(r.ci_hi, 3) + "</td></tr>";
  }).join("");
  var note = document.getElementById("task-note");
  if (note) {
    var d = taskDef(data);
    var extra = (state.task === "MB-2003") ? " " + data.meta.pairwise_note : "";
    var maj = (state.task === "MB-2001") ? " Majority baseline: 107/163 = 0.656."
            : (state.task === "MB-2002") ? " Majority baseline: 43/163 = 0.264; uniform-choice chance = 0.200."
            : "";
    note.textContent = (d.name || state.task) + "." + maj + extra;
  }
}
document.addEventListener("DOMContentLoaded", function () {
  var sel = document.getElementById("task-select");
  if (sel) sel.addEventListener("change", function () { state.task = sel.value; state.sortKey = null; render(); });
  var man = document.getElementById("manifest-select");
  if (man) man.addEventListener("change", function () { state.manifest = man.value; render(); });
  var q = document.getElementById("model-search");
  if (q) q.addEventListener("input", function () { state.query = q.value; render(); });
  var manWrap = document.getElementById("manifest-wrap");
  var manSel = document.getElementById("manifest-select");
  var syncMan = function () { if (manWrap) manWrap.style.display = (state.task === "MB-2003" ? "inline" : "none"); };
  if (sel) sel.addEventListener("change", function () { syncMan(); });
  if (manSel) manSel.addEventListener("change", function () { state.manifest = manSel.value; render(); });
  syncMan();
  var exp = document.getElementById("export-btn");
  if (exp) exp.addEventListener("click", function () {
    var a = document.createElement("a");
    a.href = "assets/leaderboard.json"; a.download = "masld-bench-eligible-leaderboard.json"; a.click();
  });
  var taskDef = window.MASLD_DATA && window.MASLD_DATA.meta.task_defs;
  render();
});
